1	#!/usr/bin/env node
2	// Usage: node jsonpatch-cli.mjs <patch> [<doc>]
3	import { open, stat } from 'node:fs/promises';
4	import { applyPatch, PatchError } from './jsonpatch.mjs';
5	
6	const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
7	const MAX_BYTES = 1048576;
8	const MAX_DEPTH = 1000;
9	const CHUNK = 65536;
10	
11	class CliError extends Error {
12	  constructor(message, code) {
13	    super(message);
14	    this.code = code;
15	  }
16	}
17	
18	const readFailure = (name, reason) => new CliError(`Error: ${name}: ${reason}`, 1);
19	
20	async function isDirectory(path) {
21	  try {
22	    return (await stat(path)).isDirectory();
23	  } catch {
24	    return false;
25	  }
26	}
27	
28	async function readFileInput(path) {
29	  let handle;
30	  try {
31	    handle = await open(path, 'r');
32	  } catch (err) {
33	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw readFailure(path, 'no such file');
34	    if (err.code === 'EISDIR' || (await isDirectory(path))) throw readFailure(path, 'is a directory');
35	    throw readFailure(path, 'cannot read');
36	  }
37	  try {
38	    if ((await handle.stat()).isDirectory()) throw readFailure(path, 'is a directory');
39	    const chunks = [];
40	    let total = 0;
41	    for (;;) {
42	      const buf = Buffer.alloc(CHUNK);
43	      const { bytesRead } = await handle.read(buf, 0, CHUNK, null);
44	      if (bytesRead === 0) break;
45	      total += bytesRead;
46	      if (total > MAX_BYTES) throw readFailure(path, 'too large');
47	      chunks.push(buf.subarray(0, bytesRead));
48	    }
49	    return Buffer.concat(chunks);
50	  } catch (err) {
51	    if (err instanceof CliError) throw err;
52	    if (err.code === 'EISDIR') throw readFailure(path, 'is a directory');
53	    throw readFailure(path, 'cannot read');
54	  } finally {
55	    await handle.close().catch(() => {});
56	  }
57	}
58	
59	function readStdin() {
60	  return new Promise((resolve, reject) => {
61	    const stdin = process.stdin;
62	    const chunks = [];
63	    let total = 0;
64	    const finish = (err) => {
65	      stdin.removeAllListeners('data');
66	      stdin.removeAllListeners('end');
67	      stdin.destroy();
68	      if (err) reject(err);
69	      else resolve(Buffer.concat(chunks));
70	    };
71	    stdin.on('data', (chunk) => {
72	      total += chunk.length;
73	      if (total > MAX_BYTES) finish(readFailure('stdin', 'too large'));
74	      else chunks.push(chunk);
75	    });
76	    stdin.on('end', () => finish(null));
77	    stdin.on('error', () => finish(readFailure('stdin', 'cannot read')));
78	  });
79	}
80	
81	function jsonDepth(value) {
82	  let max = 0;
83	  const stack = [[value, 0]];
84	  while (stack.length > 0) {
85	    const [v, depth] = stack.pop();
86	    if (v === null || typeof v !== 'object') {
87	      max = Math.max(max, depth);
88	      continue;
89	    }
90	    max = Math.max(max, depth + 1);
91	    for (const child of Array.isArray(v) ? v : Object.values(v)) stack.push([child, depth + 1]);
92	  }
93	  return max;
94	}
95	
96	async function loadInput(arg) {
97	  const name = arg === '-' ? 'stdin' : arg;
98	  const bytes = arg === '-' ? await readStdin() : await readFileInput(arg);
99	  let text;
100	  try {
101	    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
102	  } catch {
103	    throw new CliError(`Error: ${name}: invalid UTF-8`, 3);
104	  }
105	  let value;
106	  try {
107	    value = JSON.parse(text);
108	  } catch {
109	    throw new CliError(`Error: ${name}: invalid JSON`, 3);
110	  }
111	  if (jsonDepth(value) > MAX_DEPTH) throw new CliError(`Error: ${name}: too deep`, 3);
112	  return value;
113	}
114	
115	async function main(args) {
116	  if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
117	  const [patchArg, docArg = '-'] = args;
118	  if (patchArg === '-' && docArg === '-') throw new CliError(USAGE, 2);
119	  const patch = await loadInput(patchArg);
120	  const doc = await loadInput(docArg);
121	  let result;
122	  try {
123	    result = applyPatch(doc, patch);
124	  } catch (err) {
125	    if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
126	    throw err;
127	  }
128	  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
129	}
130	
131	try {
132	  await main(process.argv.slice(2));
133	} catch (err) {
134	  if (!(err instanceof CliError)) throw err;
135	  process.stderr.write(`${err.message}\n`);
136	  process.exitCode = err.code;
137	}
